rule phishing_campaign {
  meta:
    author = 'SOC Team'
  description = 'Detects phishing campaigns with typosquatted domains'
  reference = 'https://example.com/phishing_campaign'
  tags = 'phishing, credential_harvesting'

  condition:
    any of them {
      network traffic from any ip addr to any port {
        contains 'microsft-365.com' {
          within 1 of {
            http.request.uri.path == "/login"
          }
        }
      }
    }
}

